110	// gatherAnswers asks every job and returns the files to write, the fixtures that
111	// did not change and the fixtures sent with a cache effect. The first problem ends
112	// the run: nothing is written yet.
113	func gatherAnswers(ctx context.Context, o RecordOptions, jobs []recordJob) (writes []recordWrite, unchanged, sent []string, err error) {
114		r := newRecorder(o)
115		defer r.close()
116		now := time.Now
117		if o.Now != nil {
118			now = o.Now
119		}
120		date := now().Format(recordedDateLayout)
121		for _, j := range jobs {
122			data, same, err := r.record(ctx, j, date)
123			switch {
124			case err != nil:
125				return nil, nil, r.cacheEffects, err
126			case same:
127				unchanged = append(unchanged, j.name)
128			default:
129				writes = append(writes, recordWrite{name: j.name, path: j.path, data: data})
130			}
131		}
132		return writes, unchanged, r.cacheEffects, nil
133	}
