135	// record asks the bench for the answers of the job and returns the bytes of the
136	// fixture it would write; same is true when the file already holds those answers.
137	func (r *recorder) record(ctx context.Context, j recordJob, date string) (data []byte, same bool, err error) {
138		if j.current.Meta.Effect == nexusfixture.EffectCaches {
139			r.cacheEffects = append(r.cacheEffects, j.name)
140		}
141		steps, note, err := r.replay(ctx, j)
142		if err != nil {
143			return nil, false, err
144		}
145		answers := make([]nexusfixture.Exchange, len(steps))
146		for i, s := range steps {
147			answers[i] = redactAnswer(s.raw)
148		}
149		f := j.current
150		f.Meta.NexusVersion, f.Meta.Edition, f.Meta.NexusNote = r.o.Descriptor.NexusVersion, r.o.Descriptor.Edition, note
151		f.Meta.Measured, f.Meta.RecordedBy = date, recordedBy
152		if f.Meta.Record == nexusfixture.RecordPending {
153			f.Meta.Record = ""
154		}
155		f.Exchanges = answers
156		data = nexusfixture.Format(f)
157	
158		// What will be written is read back and checked, not what was built.
159		back, err := nexusfixture.Parse(j.campaign, filepath.Base(j.path), data)
160		if err != nil || !bytes.Equal(nexusfixture.Format(back), data) {
161			return nil, false, recordError("the answer to "+j.name+" does not read back as a fixture", "do not record this answer", err)
162		}
163		if leaks := nexusfixture.CheckLeaks(j.name, data, r.terms); len(leaks) > 0 {
164			return nil, false, recordError("the answer to "+j.name+" would leak: "+describeLeaks(leaks), "nothing was written; fix the bench or the redaction", nil)
165		}
166		for _, s := range steps {
167			if holdsTerm(s.raw.Header, s.raw.Body, r.termsWithout(s.issued)) {
168				return nil, false, recordError("the answer to "+j.name+" holds a bench password, a token or a denied term where the file would not show it", "nothing was written; do not record this answer", nil)
