213	// replay sends the first request of the job and follows its flow.
214	func (r *recorder) replay(ctx context.Context, j recordJob) (steps []replayStep, note string, err error) {
215		first := j.current.Exchanges[0]
216		rq := replayRequest{method: first.Method, target: first.Target, host: first.Host, header: first.RequestHeader}
217		switch j.current.Meta.Flow {
218		case nexusfixture.FlowBearer:
219			return r.bearerFlow(ctx, j, rq)
220		case nexusfixture.FlowRedirects:
221			return r.redirectFlow(ctx, j, rq)
222		}
223		s, err := r.send(ctx, j, rq, "")
224		if err != nil {
225			return nil, "", err
226		}
227		return []replayStep{s}, "", nil
228	}
