266		challenge, ok := parseBearerChallenge(call.raw.Header)
267		if !ok {
268			return steps, noteNoBearer, nil
269		}
270		tokenRequest, ok := r.tokenRequest(j, challenge)
271		if !ok {
272			return steps, noteRealm, nil
273		}
274		issued, err := r.send(ctx, j, tokenRequest, "")
275		if err != nil {
276			return nil, "", err
277		}
278		steps = append(steps, issued)
279		if issued.raw.Status != http.StatusOK {
280			return steps, noteTokenRefused, nil
281		}
282		token := tokenOf(issued.raw.Body)
283		if token == "" {
284			return nil, "", recordError("the token answer to "+j.name+" holds no token", "do not record this answer", nil)
