211	// ---- sending -----------------------------------------------------------------------
212	
213	// replay sends the first request of the job and follows its flow.
214	func (r *recorder) replay(ctx context.Context, j recordJob) (steps []replayStep, note string, err error) {
215		first := j.current.Exchanges[0]
216		rq := replayRequest{method: first.Method, target: first.Target, host: first.Host, header: first.RequestHeader}
217		switch j.current.Meta.Flow {
218		case nexusfixture.FlowBearer:
219			return r.bearerFlow(ctx, j, rq)
220		case nexusfixture.FlowRedirects:
221			return r.redirectFlow(ctx, j, rq)
222		}
223		s, err := r.send(ctx, j, rq, "")
224		if err != nil {
225			return nil, "", err
226		}
227		return []replayStep{s}, "", nil
228	}
229	
230	// send asks one request of a job, as the credentials of its identity, or with
231	// bearer as a token when it is not empty, and checks what the bench answers.
232	func (r *recorder) send(ctx context.Context, j recordJob, rq replayRequest, bearer string) (replayStep, error) {
233		c := r.client(j, r.o.Origins[rq.host])
234		status, header, body, err := c.recorded(ctx, rq.method, rq.target, rq.header, bearer)
235		if err != nil {
236			return replayStep{}, recordError("the answer to "+j.name+" could not be read", "check that the bench answers on its loopback ports", err)
237		}
238		if !benchVersionMatches(header.Get("Server"), r.o.Descriptor) {
239			return replayStep{}, recordError("the answer to "+j.name+" does not come from the Nexus version and edition the descriptor names", upCheck, nil)
240		}
241		if declaresJSON(header.Get("Content-Type")) && len(body) > 0 && !json.Valid(body) {
242			return replayStep{}, recordError("the answer to "+j.name+" is declared JSON and is not", "do not record this answer: a secret could hide from the redaction in it", nil)
243		}
244		return replayStep{raw: nexusfixture.RawExchange{
245			Method: rq.method, Target: rq.target, Host: rq.host, RequestHeader: rq.header,
246			Status: status, Header: header, Body: body,
247		}}, nil
248	}
