250	// ---- flow: bearer --------------------------------------------------------------------
251	
252	// bearerChallenge is what a WWW-Authenticate Bearer challenge asks.
253	type bearerChallenge struct{ realm, service, scope string }
254	
255	// bearerFlow sends the request, and on a Bearer challenge it can follow, asks for
256	// the token and sends the request again with it.
257	func (r *recorder) bearerFlow(ctx context.Context, j recordJob, rq replayRequest) ([]replayStep, string, error) {
258		call, err := r.send(ctx, j, rq, "")
259		if err != nil {
260			return nil, "", err
261		}
262		steps := []replayStep{call}
263		if call.raw.Status != http.StatusUnauthorized {
264			return steps, noteNoChallenge, nil
265		}
266		challenge, ok := parseBearerChallenge(call.raw.Header)
267		if !ok {
268			return steps, noteNoBearer, nil
269		}
270		tokenRequest, ok := r.tokenRequest(j, challenge)
271		if !ok {
272			return steps, noteRealm, nil
273		}
274		issued, err := r.send(ctx, j, tokenRequest, "")
275		if err != nil {
276			return nil, "", err
277		}
278		steps = append(steps, issued)
279		if issued.raw.Status != http.StatusOK {
280			return steps, noteTokenRefused, nil
281		}
282		token := tokenOf(issued.raw.Body)
283		if token == "" {
284			return nil, "", recordError("the token answer to "+j.name+" holds no token", "do not record this answer", nil)
285		}
286		// Before any check of any answer: the token is a term no file may hold.
287		r.terms = append(r.terms, token)
288		steps[len(steps)-1].issued = token
289	
290		retry := rq
291		retry.header = placeholderHeader(rq.header, "Bearer")
292		again, err := r.send(ctx, j, retry, token)
293		if err != nil {
294			return nil, "", err
295		}
296		return append(steps, again), "", nil
297	}
298	
299	// tokenRequest builds the request for the token of a challenge. It exists only when
300	// the realm is an origin of the run and a token path: anything else is not sent the
301	// credentials of the bench.
302	func (r *recorder) tokenRequest(j recordJob, c bearerChallenge) (replayRequest, bool) {
303		u, err := url.Parse(c.realm)
304		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.User != nil {
305			return replayRequest{}, false
306		}
307		if _, known := r.o.Origins[u.Host]; !known {
308			return replayRequest{}, false
309		}
310		if !nexusfixture.IsTokenPath(u.Path) || u.EscapedPath() != u.Path {
311			return replayRequest{}, false
312		}
313		query := url.Values{}
314		if c.service != "" {
315			query.Set("service", c.service)
316		}
317		if c.scope != "" {
318			query.Set("scope", c.scope)
319		}
320		target := u.Path
321		if len(query) > 0 {
322			target += "?" + query.Encode()
323		}
324		scheme := ""
325		if j.user != "" {
326			scheme = "Basic"
327		}
328		return replayRequest{
329			method: http.MethodGet, target: target, host: u.Host,
330			header: placeholderHeader(http.Header{"Accept": {tokenAccept}}, scheme),
331		}, true
332	}
333	
334	// parseBearerChallenge reads the first Bearer challenge of an answer.
335	func parseBearerChallenge(h http.Header) (bearerChallenge, bool) {
336		for _, v := range h.Values("WWW-Authenticate") {
337			if len(v) < len("Bearer ") || !strings.EqualFold(v[:len("Bearer")], "Bearer") || v[len("Bearer")] != ' ' {
338				continue
339			}
340			var c bearerChallenge
341			for _, m := range challengeParam.FindAllStringSubmatch(v[len("Bearer "):], -1) {
342				switch strings.ToLower(m[1]) {
343				case "realm":
344					c.realm = m[2]
345				case "service":
346					c.service = m[2]
347				case "scope":
348					c.scope = m[2]
349				}
350			}
351			if c.realm != "" {
352				return c, true
353			}
354		}
355		return bearerChallenge{}, false
356	}
357	
358	// tokenOf reads the token of a token answer, "" when it holds none.
359	func tokenOf(body []byte) string {
360		var answer struct {
361			Token       string `json:"token"`
362			AccessToken string `json:"access_token"`
363		}
364		if json.Unmarshal(body, &answer) != nil {
365			return ""
366		}
367		return cmp.Or(answer.Token, answer.AccessToken)
368	}
